import React from "react";
import { motion } from "framer-motion";
import { FEATURES } from "../types";
import { Palette, Ruler, Package, Truck, Award, Heart, LucideIcon } from "lucide-react";

const iconMap: Record<string, LucideIcon> = {
  Palette,
  Ruler,
  Package,
  Truck,
  Award,
  Heart,
};

export default function Features() {
  return (
    <section className="py-24 lg:py-32 bg-gradient-to-b from-gray-50 to-white">
      <div className="container mx-auto px-6">
        {/* Header */}
        <motion.div
          className="text-center mb-16"
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
        >
          <motion.div className="flex items-center justify-center gap-4 mb-6">
            <div className="h-px w-12 bg-gradient-to-r from-transparent to-amber-400" />
            <span className="text-sm font-semibold tracking-[0.15em] uppercase text-amber-500">Why Choose Us</span>
            <div className="h-px w-12 bg-gradient-to-l from-transparent to-amber-400" />
          </motion.div>
          <h2 className="text-4xl md:text-5xl font-bold text-gray-900" style={{ fontFamily: "Georgia, serif" }}>
            What makes us <span className="text-amber-500">different</span>
          </h2>
        </motion.div>

        {/* Grid */}
        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
          {FEATURES.map((feature, i) => {
            const Icon = iconMap[feature.icon] || Award;
            return (
              <motion.div
                key={feature.title}
                className="group relative bg-white rounded-3xl p-8 shadow-lg shadow-gray-100"
                initial={{ opacity: 0, y: 40 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ delay: i * 0.1, duration: 0.5 }}
                whileHover={{ y: -8, boxShadow: "0 25px 50px rgba(0,0,0,0.1)" }}
              >
                {/* Icon */}
                <motion.div
                  className="w-16 h-16 rounded-2xl bg-gradient-to-br from-amber-100 to-amber-200 flex items-center justify-center mb-6 group-hover:from-amber-400 group-hover:to-amber-500 transition-all duration-300"
                  whileHover={{ scale: 1.1, rotate: 5 }}
                >
                  <Icon
                    size={28}
                    className="text-amber-600 group-hover:text-white transition-colors"
                  />
                </motion.div>

                <h3 className="text-xl font-semibold text-gray-900 mb-3">
                  {feature.title}
                </h3>
                <p className="text-gray-600 leading-relaxed">
                  {feature.desc}
                </p>

                {/* Hover Accent */}
                <div className="absolute bottom-0 left-0 right-0 h-1 bg-gradient-to-r from-amber-400 to-amber-500 rounded-b-3xl opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
              </motion.div>
            );
          })}
        </div>
      </div>
    </section>
  );
}
